section.programlisting:
let a f64x4(1.0, 2.0, 3.0, 4.0)
let big a > 2.5
print "`big.count()` lanes above 2.5, any: `big.any()`, all: `big.all()`"
let clipped select(big, f64x4.splat(2.5), a)
print "`clipped[0]` `clipped[1]` `clipped[2]` `clipped[3]`"
print "sum `a.sum()`, largest `a.max_lane()`"

function dot(a: Vector[double], b: Vector[double]) returns double
{
    var acc f64x4.splat(0.0)
    var i: size_t 0
    while i + 4 <= a.length
    {
        acc := f64x4.load(a, i).fma(f64x4.load(b, i), acc)
        i := i + 4
    }
    var sum acc.sum()
    while i < a.length
    {
        sum := sum + a[i] * b[i]
        i := i + 1
    }
    sum
}

let n 1001
var a Vector[double](n as size_t)
var b Vector[double](n as size_t)
for i in n
{
    a.put(i as size_t, (i as double) * 0.5)
    b.put(i as size_t, 2.0)
}
print "a · b = `dot(a, b)`"

function count8(x: int, y: int, n: int) returns int { let step 2.0 / (n as double) let ci f64x4.splat(step * (y as double) - 1.0) let cr0 f64x4.iota(step * (x as double) - 1.5, step) let cr1 cr0 + 4.0 * step var zr0 cr0 var zi0 ci var zr1 cr1 var zi1 ci var s0 f64x4.splat(0.0) var s1 s0 var block 0 while block < 6 { var k 0 while k < 8 { let r0 zr0 * zr0 let i0 zi0 * zi0 let ri0 zr0 * zi0 s0 := r0 + i0 zr0 := r0 - i0 + cr0 zi0 := ri0 + ri0 + ci let r1 zr1 * zr1 let i1 zi1 * zi1 let ri1 zr1 * zi1 s1 := r1 + i1 zr1 := r1 - i1 + cr1 zi1 := ri1 + ri1 + ci k := k + 1 } if ((s0 <= 4.0) or (s1 <= 4.0)).any() = false return 0 block := block + 1 } var k 0 while k < 2 { let r0 zr0 * zr0 let i0 zi0 * zi0 let ri0 zr0 * zi0 s0 := r0 + i0 zr0 := r0 - i0 + cr0 zi0 := ri0 + ri0 + ci let r1 zr1 * zr1 let i1 zi1 * zi1 let ri1 zr1 * zi1 s1 := r1 + i1 zr1 := r1 - i1 + cr1 zi1 := ri1 + ri1 + ci k := k + 1 } (s0 <= 4.0).count() + (s1 <= 4.0).count() }
function row_count(y: int, n: int) returns int { var count 0 var x 0 while x < n { count := count + count8(x, y, n) x := x + 8 } count }
let n 2000 var counts Vector[int](n as size_t) for y in n counts.put(y as size_t, row_count(y, n))
var total 0 for c in counts total := total + c print "mandelbrot `n`: `total` points inside"

let n 1000
var xs Vector[double](n as size_t)
for i in n
    xs.put(i as size_t, i as double)

var ys Vector[double](n as size_t)
for k in n / 4
{
    let v f64x4.load(xs, (4 * k) as size_t)
    (v * 2.0).store(ys, (4 * k) as size_t)
}
print "ys[999] = `ys[999]`"
